def shapes(g):
    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in g]; res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
                        if 0<=x<H and 0<=y<W and g[x][y] and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                res.append(cells)
    return res

def transform(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    for _ in range(H*W):
        moved=False
        for cells in shapes(g):
            # try shift right by 1
            vals={g[i][j] for i,j in cells}
            new={(i,j+1) for i,j in cells}
            if all(0<=j<W for _,j in new) and all(not(g[i][j] and (i,j) not in cells) for i,j in new):
                for i,j in cells: g[i][j]=0
                for i,j in new: g[i][j]=next(iter(vals))
